WITH START_NAV AS (SELECT RESTORED_ACCU_NAV AS `期初复权净值` FROM FUND_NETVALUE WHERE FUND_NAME LIKE '%中欧医疗健康混合A%' AND TRADING_DAY <= '2025-12-31' AND RESTORED_ACCU_NAV IS NOT NULL AND HISVALID = 1 ORDER BY TRADING_DAY DESC LIMIT 1), END_NAV AS (SELECT FUND_NAME AS `基金名称`, FUND_SYMBOL AS `基金代码`, TRADING_DAY AS `最新交易日`, RESTORED_ACCU_NAV AS `最新复权净值` FROM FUND_NETVALUE WHERE FUND_NAME LIKE '%中欧医疗健康混合A%' AND TRADING_DAY <= '2026-09-02' AND RESTORED_ACCU_NAV IS NOT NULL AND HISVALID = 1 ORDER BY TRADING_DAY DESC LIMIT 1) SELECT E.`基金名称`, E.`基金代码`, E.`最新交易日`, S.`期初复权净值`, E.`最新复权净值`, ROUND((E.`最新复权净值` / S.`期初复权净值` - 1) * 100, 2) AS `今年以来收益率(%)` FROM END_NAV E CROSS JOIN START_NAV S;
